{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "PET imaging in baboons showed [11C]10 penetrated the BBB and regional brain uptake matched 5-HT1A receptor distribution; this close butyl-arylpiperazine-dione analogue is direct evidence of meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "FECUMI-101, a fluoroethyl analogue of CUMI-101, effectively crossed the BBB in baboon PET studies, directly demonstrating CNS penetration for the same arylpiperazine-butyl tracer class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "[123I]-BPB exhibited high brain uptake (4.99 %ID/g at 10 min) in mice, confirming robust BBB permeability for the arylpiperazine-butyl tracer scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "NGB 2904 entered the brain quickly and showed high brain penetration after IV administration, supporting CNS access for the arylpiperazine-butyl heterocycle chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "CJB 090 entered the brain quickly and demonstrated high brain penetration after IV administration, further supporting the chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "N-methylspiperone PET tracers cross the BBB easily and are used for CNS receptor imaging; the high transfer score reinforces that this structural family is brain-penetrant.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues—CUMI-101/FECUMI-101, [123I]-BPB, NGB 2904, CJB 090, and NMSP—show direct, robust BBB penetration in vivo. The query shares the key butyl-arylpiperazine and heterocyclic dione features, and replacing the aryl group with 2-fluorophenyl is a conservative, commonly CNS-permeable modification. Therefore meaningful CNS access is predicted.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule",
    "Efflux-transporter (P-gp/BCRP) status not explicitly measured for the query",
    "Species differences (baboon/mouse/rat vs human) are not directly addressed"
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C06", "C12", "C10", "C01", "C08"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "butyl-arylpiperazine CNS tracers"
    }
  ],
  "revision_action": "initial"
}

